mapper.sql:
rta_match_in_season AS (
    SELECT m.replay_id AS rid, m.played_at AS date_add, m.winner_wizard_id, m.battle_type
    FROM public.rta_match m
    WHERE 1 = 1

        AND m.played_at >= #{seasonStart}
        AND m.played_at < #{seasonEnd}

)

mapper.select:
WITH rms AS ( SELECT m.replay_id AS rid, m.played_at AS date_add, m.battle_type, TRIM(BOTH FROM m.winner_wizard_id::text) AS winner_wizard_id FROM public.rta_match m WHERE 1 = 1
AND m.played_at >= #{seasonStart} AND m.played_at < #{seasonEnd}
), user_info AS ( SELECT p.replay_id, TRIM(BOTH FROM p.wizard_id::text) AS wizard_id, p.wizard_name, p.channel_uid, p.country_code AS country, CAST(p.ladder_score AS text) AS score, CAST(p.rating_id AS text) AS rating, CASE WHEN p.is_winner THEN '1' ELSE '0' END AS result, CASE WHEN p.is_first_pick THEN '1' ELSE '0' END AS first_pick, p.alive_count, p.leader_pick_slot, (SELECT ub.unit_master_id::text FROM public.rta_match_unit_pick ub WHERE ub.replay_id = p.replay_id AND ub.wizard_id = p.wizard_id AND ub.is_banned = true LIMIT 1) AS banned_unit FROM public.rta_match_participant p INNER JOIN rms ON rms.rid = p.replay_id ), unit_info AS ( SELECT u.replay_id, u.wizard_id, array_agg(u.unit_master_id::text ORDER BY u.pick_slot_no) AS picked_units, array_agg('/images/' || mo.element_code || '/' || replace(mo.monster_name, ' ', '_') || '_' || mo.element_code || '_Icon.png' ORDER BY u.pick_slot_no) AS unit_images, array_agg(mo.monster_name ORDER BY u.pick_slot_no) AS unit_names, string_agg(u.unit_master_id::text, ',' ORDER BY u.pick_slot_no) AS picked_units_str FROM public.rta_match_unit_pick u LEFT JOIN public.rta_monster mo ON mo.unit_master_id = u.unit_master_id INNER JOIN rms ON rms.rid = u.replay_id WHERE NOT u.is_banned GROUP BY u.replay_id, u.wizard_id ), pair AS ( SELECT rms.rid, MIN(ui.wizard_id) AS p1w, MAX(ui.wizard_id) AS p2w FROM rms JOIN user_info ui ON ui.replay_id = rms.rid GROUP BY rms.rid HAVING COUNT(*) = 2 ) SELECT rms.rid, rms.battle_type, rms.date_add, CASE WHEN rms.winner_wizard_id = pr.p1w THEN '1' ELSE '2' END AS winner_position, u1.wizard_id AS p1_wizard_id, u1.channel_uid AS p1_channel_uid, u1.wizard_name AS p1_name, u1.country AS p1_country, u1.score AS p1_score, u1.rating AS p1_rating, u1.result AS p1_result, u1.first_pick AS p1_first_pick, u1.alive_count AS p1_alive_count, u1.banned_unit AS p1_banned_unit, u1.leader_pick_slot AS p1_leader_unit, COALESCE(un1.picked_units, ARRAY[]::text[]) AS p1_units, COALESCE(un1.unit_images, ARRAY[]::text[]) AS p1_unit_images, COALESCE(un1.unit_names, ARRAY[]::text[]) AS p1_unit_names, COALESCE(un1.picked_units_str, '') AS p1_units_str, u2.wizard_id AS p2_wizard_id, u2.channel_uid AS p2_channel_uid, u2.wizard_name AS p2_name, u2.country AS p2_country, u2.score AS p2_score, u2.rating AS p2_rating, u2.result AS p2_result, u2.first_pick AS p2_first_pick, u2.alive_count AS p2_alive_count, u2.banned_unit AS p2_banned_unit, u2.leader_pick_slot AS p2_leader_unit, COALESCE(un2.picked_units, ARRAY[]::text[]) AS p2_units, COALESCE(un2.unit_images, ARRAY[]::text[]) AS p2_unit_images, COALESCE(un2.unit_names, ARRAY[]::text[]) AS p2_unit_names, COALESCE(un2.picked_units_str, '') AS p2_units_str FROM rms JOIN pair pr ON pr.rid = rms.rid JOIN user_info u1 ON u1.replay_id = rms.rid AND u1.wizard_id = pr.p1w JOIN user_info u2 ON u2.replay_id = rms.rid AND u2.wizard_id = pr.p2w LEFT JOIN unit_info un1 ON un1.replay_id = rms.rid AND TRIM(BOTH FROM un1.wizard_id::text) = u1.wizard_id LEFT JOIN unit_info un2 ON un2.replay_id = rms.rid AND TRIM(BOTH FROM un2.wizard_id::text) = u2.wizard_id ORDER BY rms.date_add DESC NULLS LAST LIMIT #{limit} OFFSET #{offset}

WITH rms AS ( SELECT m.replay_id AS rid, m.played_at AS date_add, m.battle_type, TRIM(BOTH FROM m.winner_wizard_id::text) AS winner_wizard_id FROM public.rta_match m WHERE 1 = 1
AND m.played_at >= #{seasonStart} AND m.played_at < #{seasonEnd}
), user_info AS ( SELECT p.replay_id, TRIM(BOTH FROM p.wizard_id::text) AS wizard_id, p.wizard_name, p.channel_uid, p.country_code AS country, CAST(p.ladder_score AS text) AS score, CAST(p.rating_id AS text) AS rating, CASE WHEN p.is_winner THEN '1' ELSE '0' END AS result, CASE WHEN p.is_first_pick THEN '1' ELSE '0' END AS first_pick, p.alive_count, p.leader_pick_slot, (SELECT ub.unit_master_id::text FROM public.rta_match_unit_pick ub WHERE ub.replay_id = p.replay_id AND ub.wizard_id = p.wizard_id AND ub.is_banned = true LIMIT 1) AS banned_unit FROM public.rta_match_participant p INNER JOIN rms ON rms.rid = p.replay_id ), unit_info AS ( SELECT u.replay_id, u.wizard_id, array_agg(u.unit_master_id::text ORDER BY u.pick_slot_no) AS picked_units, array_agg('/images/' || mo.element_code || '/' || replace(mo.monster_name, ' ', '_') || '_' || mo.element_code || '_Icon.png' ORDER BY u.pick_slot_no) AS unit_images, array_agg(mo.monster_name ORDER BY u.pick_slot_no) AS unit_names, string_agg(u.unit_master_id::text, ',' ORDER BY u.pick_slot_no) AS picked_units_str FROM public.rta_match_unit_pick u LEFT JOIN public.rta_monster mo ON mo.unit_master_id = u.unit_master_id INNER JOIN rms ON rms.rid = u.replay_id WHERE NOT u.is_banned GROUP BY u.replay_id, u.wizard_id ), pair AS ( SELECT rms.rid, MIN(ui.wizard_id) AS p1w, MAX(ui.wizard_id) AS p2w FROM rms JOIN user_info ui ON ui.replay_id = rms.rid GROUP BY rms.rid HAVING COUNT(*) = 2 ) SELECT rms.rid, rms.battle_type, rms.date_add, CASE WHEN rms.winner_wizard_id = pr.p1w THEN '1' ELSE '2' END AS winner_position, u1.wizard_id AS p1_wizard_id, u1.channel_uid AS p1_channel_uid, u1.wizard_name AS p1_name, u1.country AS p1_country, u1.score AS p1_score, u1.rating AS p1_rating, u1.result AS p1_result, u1.first_pick AS p1_first_pick, u1.alive_count AS p1_alive_count, u1.banned_unit AS p1_banned_unit, u1.leader_pick_slot AS p1_leader_unit, COALESCE(un1.picked_units, ARRAY[]::text[]) AS p1_units, COALESCE(un1.unit_images, ARRAY[]::text[]) AS p1_unit_images, COALESCE(un1.unit_names, ARRAY[]::text[]) AS p1_unit_names, COALESCE(un1.picked_units_str, '') AS p1_units_str, u2.wizard_id AS p2_wizard_id, u2.channel_uid AS p2_channel_uid, u2.wizard_name AS p2_name, u2.country AS p2_country, u2.score AS p2_score, u2.rating AS p2_rating, u2.result AS p2_result, u2.first_pick AS p2_first_pick, u2.alive_count AS p2_alive_count, u2.banned_unit AS p2_banned_unit, u2.leader_pick_slot AS p2_leader_unit, COALESCE(un2.picked_units, ARRAY[]::text[]) AS p2_units, COALESCE(un2.unit_images, ARRAY[]::text[]) AS p2_unit_images, COALESCE(un2.unit_names, ARRAY[]::text[]) AS p2_unit_names, COALESCE(un2.picked_units_str, '') AS p2_units_str FROM rms JOIN pair pr ON pr.rid = rms.rid JOIN user_info u1 ON u1.replay_id = rms.rid AND u1.wizard_id = pr.p1w JOIN user_info u2 ON u2.replay_id = rms.rid AND u2.wizard_id = pr.p2w LEFT JOIN unit_info un1 ON un1.replay_id = rms.rid AND TRIM(BOTH FROM un1.wizard_id::text) = u1.wizard_id LEFT JOIN unit_info un2 ON un2.replay_id = rms.rid AND TRIM(BOTH FROM un2.wizard_id::text) = u2.wizard_id WHERE (u1.wizard_id = #{wizardId} OR u2.wizard_id = #{wizardId}) ORDER BY rms.date_add DESC NULLS LAST LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE public.rta_match
SET synergy_applied_at = CURRENT_TIMESTAMP
WHERE replay_id = #{rid}

UPDATE public.rta_match
SET synergy_applied_at = CURRENT_TIMESTAMP
WHERE replay_id = #{rid}

mapper.select:
WITH , latest AS ( SELECT DISTINCT ON (u.wizard_id) u.wizard_id, u.wizard_name, u.country_code AS country, u.channel_uid, CAST(TRIM(u.ladder_score::text) AS INT) AS score, CASE WHEN TRIM(COALESCE(u.rating_id::text, '')) ~ '^[0-9]+$' THEN CAST(TRIM(u.rating_id::text) AS INT) ELSE NULL END AS rating_id, r.date_add AS last_match_at FROM public.rta_match_participant u INNER JOIN rta_match_in_season r ON u.replay_id = r.rid WHERE TRIM(COALESCE(u.ladder_score::text, '')) ~ '^[0-9]+$' AND CAST(TRIM(u.ladder_score::text) AS INT) > 0 ORDER BY u.wizard_id, r.date_add DESC ), ranked AS ( SELECT latest.wizard_id, latest.wizard_name, latest.country, latest.channel_uid, latest.score, latest.rating_id, latest.last_match_at, ROW_NUMBER() OVER (ORDER BY latest.score DESC, latest.wizard_id ASC) AS rank_position FROM latest ), ranked_filtered AS ( SELECT r.* FROM ranked r WHERE 1 = 1
AND ( CASE WHEN TRIM(COALESCE(r.country::text, '')) = '' THEN '—' ELSE TRIM(r.country::text) END ) = #{countryFilter}
) SELECT COUNT(*)::int FROM ranked_filtered

WITH , , latest AS ( SELECT DISTINCT ON (u.wizard_id) u.wizard_id, u.wizard_name, u.country_code AS country, u.channel_uid, CAST(TRIM(u.ladder_score::text) AS INT) AS score, CASE WHEN TRIM(COALESCE(u.rating_id::text, '')) ~ '^[0-9]+$' THEN CAST(TRIM(u.rating_id::text) AS INT) ELSE NULL END AS rating_id, r.date_add AS last_match_at FROM public.rta_match_participant u INNER JOIN rta_match_in_season r ON u.replay_id = r.rid WHERE TRIM(COALESCE(u.ladder_score::text, '')) ~ '^[0-9]+$' AND CAST(TRIM(u.ladder_score::text) AS INT) > 0 ORDER BY u.wizard_id, r.date_add DESC ), ranked AS ( SELECT latest.wizard_id, latest.wizard_name, latest.country, latest.channel_uid, latest.score, latest.rating_id, latest.last_match_at, ROW_NUMBER() OVER (ORDER BY latest.score DESC, latest.wizard_id ASC) AS rank_position FROM latest ), ranked_filtered AS ( SELECT r.* FROM ranked r WHERE 1 = 1
AND ( CASE WHEN TRIM(COALESCE(r.country::text, '')) = '' THEN '—' ELSE TRIM(r.country::text) END ) = #{countryFilter}
), score_max_agg AS ( SELECT u.wizard_id, MAX(CAST(TRIM(u.ladder_score::text) AS INT))::int AS max_season_score FROM public.rta_match_participant u INNER JOIN rta_match_in_season r ON u.replay_id = r.rid WHERE TRIM(COALESCE(u.ladder_score::text, '')) ~ '^[0-9]+$' AND CAST(TRIM(u.ladder_score::text) AS INT) > 0 GROUP BY u.wizard_id ), page_ranked AS ( SELECT * FROM ranked_filtered ORDER BY rank_position LIMIT #{limit} OFFSET #{offset} ), field_pick_counts AS ( SELECT u.wizard_id, TRIM(BOTH FROM u.unit_master_id::text) AS unit_master_id, COUNT(*)::bigint AS pick_count FROM public.rta_match_unit_pick u WHERE TRIM(BOTH FROM COALESCE(u.unit_master_id::text, '')) ~ '^[0-9]+$' AND NOT u.is_banned AND u.wizard_id IN (SELECT wizard_id FROM page_ranked) GROUP BY u.wizard_id, TRIM(BOTH FROM u.unit_master_id::text) ), ranked_monsters AS ( SELECT wizard_id, unit_master_id, pick_count, ROW_NUMBER() OVER ( PARTITION BY wizard_id ORDER BY pick_count DESC, CAST(unit_master_id AS BIGINT) ASC ) AS rn FROM field_pick_counts ), most1 AS ( SELECT wizard_id, unit_master_id AS m1_id, pick_count AS m1_pick FROM ranked_monsters WHERE rn = 1 ), most2 AS ( SELECT wizard_id, unit_master_id AS m2_id, pick_count AS m2_pick FROM ranked_monsters WHERE rn = 2 ), most3 AS ( SELECT wizard_id, unit_master_id AS m3_id, pick_count AS m3_pick FROM ranked_monsters WHERE rn = 3 ) SELECT pr.rank_position, pr.wizard_id, pr.wizard_name, pr.country, pr.channel_uid, pr.score, pr.rating_id, pr.last_match_at, COALESCE(wa.match_count, 0)::bigint AS match_count, COALESCE(wa.win_count, 0)::bigint AS win_count, COALESCE(sm.max_season_score, pr.score)::int AS max_season_score, m1.m1_id::text AS most_monster_1_id, m1.m1_pick AS most_monster_1_pick_count, COALESCE(mm1.monster_name, '') AS most_monster_1_name, CASE WHEN mm1.monster_name IS NOT NULL THEN '/images/' || mm1.element_code || '/' || replace(mm1.monster_name, ' ', '_') || '_' || mm1.element_code || '_Icon.png' ELSE '' END AS most_monster_1_image, m2.m2_id::text AS most_monster_2_id, m2.m2_pick AS most_monster_2_pick_count, COALESCE(mm2.monster_name, '') AS most_monster_2_name, CASE WHEN mm2.monster_name IS NOT NULL THEN '/images/' || mm2.element_code || '/' || replace(mm2.monster_name, ' ', '_') || '_' || mm2.element_code || '_Icon.png' ELSE '' END AS most_monster_2_image, m3.m3_id::text AS most_monster_3_id, m3.m3_pick AS most_monster_3_pick_count, COALESCE(mm3.monster_name, '') AS most_monster_3_name, CASE WHEN mm3.monster_name IS NOT NULL THEN '/images/' || mm3.element_code || '/' || replace(mm3.monster_name, ' ', '_') || '_' || mm3.element_code || '_Icon.png' ELSE '' END AS most_monster_3_image FROM page_ranked pr LEFT JOIN win_agg wa ON pr.wizard_id = wa.wizard_id LEFT JOIN score_max_agg sm ON pr.wizard_id = sm.wizard_id LEFT JOIN most1 m1 ON pr.wizard_id = m1.wizard_id LEFT JOIN public.rta_monster mm1 ON m1.m1_id IS NOT NULL AND TRIM(BOTH FROM m1.m1_id::text) ~ '^[0-9]+$' AND mm1.unit_master_id = CAST(TRIM(BOTH FROM m1.m1_id::text) AS bigint) LEFT JOIN most2 m2 ON pr.wizard_id = m2.wizard_id LEFT JOIN public.rta_monster mm2 ON m2.m2_id IS NOT NULL AND TRIM(BOTH FROM m2.m2_id::text) ~ '^[0-9]+$' AND mm2.unit_master_id = CAST(TRIM(BOTH FROM m2.m2_id::text) AS bigint) LEFT JOIN most3 m3 ON pr.wizard_id = m3.wizard_id LEFT JOIN public.rta_monster mm3 ON m3.m3_id IS NOT NULL AND TRIM(BOTH FROM m3.m3_id::text) ~ '^[0-9]+$' AND mm3.unit_master_id = CAST(TRIM(BOTH FROM m3.m3_id::text) AS bigint) ORDER BY pr.rank_position
